Translate the following GNU C++11 code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <bits/stdc++.h>
#define MAXN 5000010
#define INF 1000000000
#define IDX(x,k) (x+(k-1)*n)
using namespace std;
template<typename T> inline void read_input(T &x)
{
    x=0;char c=getchar();bool neg=false;
    while(!isdigit(c)){if(c=='-')neg=true;c=getchar();}
    while(isdigit(c)){x=(x<<1)+(x<<3)+(c^48);c=getchar();}
    if(neg)x=-x;
}
int n,m,k,v1,v2,s,t;
int dist[MAXN];
bool visited[MAXN];
struct Edge
{
    int to,next,v,cost;
}edges[MAXN];
int head[MAXN],edgeCount=1;
void addEdge(int from,int to,int val,int cost)
{
    edges[++edgeCount]=(Edge){to,head[from],val,cost}; head[from]=edgeCount;
    edges[++edgeCount]=(Edge){from,head[to],0,-cost}; head[to]=edgeCount;
}
bool spfa()
{
    queue<int> q;
    for(int i=s;i<=t;++i) dist[i]=INF,visited[i]=false;
    q.push(s); dist[s]=0; visited[s]=true;
    while(!q.empty())
    {
        int x=q.front(); q.pop(); visited[x]=false;
        for(int i=head[x];i;i=edges[i].next)
        {
            int y=edges[i].to,c=edges[i].cost;
            if(dist[y]<=dist[x]+c||!edges[i].v) continue;
            dist[y]=dist[x]+c;
            if(!visited[y]) {visited[y]=true; q.push(y);}
        }
    }
    return dist[t]!=INF;
}
int dfs(int x,int limit)
{
    if(x==t) return limit;
    visited[x]=true;
    int flow,res=limit;
    for(int i=head[x];i;i=edges[i].next)
    {
        int y=edges[i].to,v=edges[i].v;
        if(dist[y]!=dist[x]+edges[i].cost||!v||visited[y]) continue;
        if((flow=dfs(y,min(res,v))))
        {
            res-=flow;
            edges[i].v-=flow;
            edges[i^1].v+=flow;
            if(!res) break;
        }
    }
    return limit-res;
}
int maxFlow()
{
    int totalFlow=0, flow;
    while(spfa())
        while(flow=dfs(s,INF))
            totalFlow+=flow*dist[t];
    return totalFlow;
}
int main()
{
    read_input(n); read_input(m); read_input(k); read_input(v1); read_input(v2);
    t=IDX(n,110)+1;
    for(int i=2;i<=110;++i) addEdge(IDX(1,i),t,INF,0);
    for(int i=2;i<=n;++i)
        for(int j=1;j<110;++j)
            addEdge(IDX(i,j),IDX(i,j+1),INF,v1);
    for(int i=1,x;i<=k;++i) {read_input(x); addEdge(s,IDX(x,1),1,0);}
    for(int i=1;i<=m;++i)
    {
        int x,y;
        read_input(x); read_input(y);
        for(int j=1;j<110;++j)
            for(int l=1;l<=k;++l)
                addEdge(IDX(x,j),IDX(y,j+1),1,v2*(2*l-1)+v1),
                addEdge(IDX(y,j),IDX(x,j+1),1,v2*(2*l-1)+v1);
    }
    printf("%d",maxFlow());
    return 0;
}
